independent_A_ideal_script:
R=QQ[a,b,c,d,e];
M=matrix{{-3*c/5,-3*d/10,0,0,d/10,0,3*b/2 - 3*e/5,0,0,7*c/5,-d/10,0},{3*b/5 - 9*e/10,29*c/5,-4*d/5,0,7*c/5,d/5,3*a/2,2*b - e,0,13*b/5 + e/2,13*c/5,-2*d/5},{2*a/5,4*b/5 + 7*e/5,37*c/10,-3*d/2,-b/10 + 4*e/5,17*c/10,0,a,3*b/2 - 6*e/5,2*a/5,11*b/10 + e/5,13*c/5},{0,-a/5,4*b/5 + e/20,c,-a/10,4*b/5 + e/20,0,0,a/2,0,a/10,2*b/5 + e/10}};
I=minors(4,M);
P=ideal(c,d,5*b-2*e);
Q=ideal(5*b-e,5*a*d-6*c*e,20*c^2+3*d*e,50*a*c+9*e^2);
J=intersect(P,Q);
assert (numgens J==6);
assert (dim(R/I)==2 and dim(R/J)==2);
assert isSubset(I,J);
assert all(flatten entries gens J,x->(x^2)%I==0);
print("REVIEW_PASS: dimension2; six square containments; ideal containment");
